黑猫点点

/*

 * =======================================================

 *   最终定稿+图片镶嵌：外细灰边+纯白带+柔化灰底气泡

 *   新增：AI气泡右下角镶嵌图片1 | 用户气泡右下角镶嵌图片2

 * =======================================================

*/



/* --- 1. 基础容器净化 (清除默认样式) --- */

.message-bubble.user .content,

.message-bubble.ai .content {

    background: transparent !important;

    border: none !important;

    border-radius: 0 !important;

    box-shadow: none !important;

    position: relative;

    z-index: 1;

}



/* --- 2. 核心气泡样式 (3层结构+预留图片位置) --- */

.message-bubble.user .content::before,

.message-bubble.ai .content::before {

    content: '';

    position: absolute;

    top: 0; left: 0; right: 0; bottom: 0;

    z-index: -1;

    outline: 1.2px double #E0E0E0 !important; /* 外层细灰边 */

    border: 4px solid #FFFFFF !important; /* 中层纯白带 */

    background: rgba(240, 240, 240, 0.85) !important; /* 内层柔化灰底 */

    backdrop-filter: blur(2px) !important;

    -webkit-backdrop-filter: blur(2px) !important;

    border-radius: 14px !important;

    background-clip: padding-box !important;

}



/* --- 3. AI气泡 (左侧)：右下角镶嵌图片1 (贴合边框) --- */

.message-bubble.ai .content::before {

    background: rgba(245, 245, 245, 0.88) !important;

}

.message-bubble.ai .content {

    padding: 7px 12px 5px 9px !important;

    color: #333333 !important;

    width: fit-content;

    max-width: 230px;

    word-wrap: break-word;

}

/* AI气泡右下角图片：镶嵌在边框上 */

.message-bubble.ai .content::after {

    content: '';

    position: absolute;

    bottom: -4px; /* 贴合边框底部 */

    right: -4px; /* 贴合边框右侧 */

    z-index: 2; /* 悬浮于边框之上，不遮挡 */

    width: 16px; /* 图片宽度，可按需调整 */

    height: 16px; /* 图片高度，可按需调整 */

    background-image: url('https://cdn.jsdelivr.net.cn/gh/xxloli/tc/fkfrge2kjg.png') !important;

    background-size: 100% 100% !important;

    background-repeat: no-repeat !important;

    background-position: center !important;

}



/* --- 4. 用户气泡 (右侧)：右下角镶嵌图片2 (贴合边框) --- */

.message-bubble.user .content::before {

    background: rgba(240, 240, 240, 0.88) !important;

    outline: 1.2px double #D8D8D8 !important;

}

.message-bubble.user .content {

    padding: 7px 9px 5px 12px !important;

    color: #222222 !important;

    width: fit-content;

    max-width: 230px;

    word-wrap: break-word;

}

/* 用户气泡右下角图片：镶嵌在边框上 */

.message-bubble.user .content::after {

    content: '';

    position: absolute;

    bottom: -4px; /* 贴合边框底部 */

    right: -4px; /* 贴合边框右侧 */

    z-index: 2; /* 悬浮于边框之上，不遮挡 */

    width: 16px; /* 图片宽度，可按需调整 */

    height: 16px; /* 图片高度，可按需调整 */

    background-image: url('https://file.icve.com.cn/file_doc/qdqqd/7011765884855751.png') !important;

    background-size: 100% 100% !important;

    background-repeat: no-repeat !important;

    background-position: center !important;

}



/* --- 5. 转账卡片样式 --- */

.message-bubble .transfer-card {

    background: linear-gradient(135deg, #F5F5F5, #FFFFFF) !important;

    border: 1px solid #E0E0E0 !important;

    border-radius: 10px !important;

    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04) !important;

    padding: 12px 16px !important;

    width: 220px;

    animation: none !important;

}

.message-bubble .transfer-card .transfer-amount,

.message-bubble .transfer-card .transfer-note,

.message-bubble .transfer-card .transfer-status {

    color: #555555 !important;

}



/* --- 6. 特殊内容适配 --- */

.message-bubble .content:has(.sticker-container),

.message-bubble .content:has(.transfer-card) {

    padding: 0 !important;

    backdrop-filter: none !important;

    -webkit-backdrop-filter: none !important;

}

.message-bubble .content:has(.sticker-container)::before,

.message-bubble .content:has(.transfer-card)::before,

.message-bubble .content:has(.sticker-container)::after,

.message-bubble .content:has(.transfer-card)::after {

    display: none !important; /* 特殊内容隐藏气泡背景和图片 */

}



.message-bubble .content:has(img),

.message-bubble .content:has(.image-message),

.message-bubble .content:has(pre),

.message-bubble .content:has(code) {

    background: transparent !important;

    padding: 8px 12px !important;

    outline: none !important;

    border: none !important;

    backdrop-filter: none !important;

}

.message-bubble .content:has(img)::before,

.message-bubble .content:has(pre)::before,

.message-bubble .content:has(img)::after,

.message-bubble .content:has(pre)::after {

    display: none !important;

}

