import random
import numpy as np
from collections import defaultdict

class NameGenerator:
    def __init__(self):
        self.surname_db = self._load_surnames()
        self.char_db = {
            'male': {
                'ancient': self._load_ancient_chars('male'),
                'modern': self._load_modern_chars('male'),
                'western': self._load_western_elements('male')
            },
            'female': {
                'ancient': self._load_ancient_chars('female'),
                'modern': self._load_modern_chars('female'),
                'western': self._load_western_elements('female')
            }
        }

        # 记录字符使用频率
        self.char_usage = defaultdict(int)
        self.name_history = set()

        # 优化后的风格权重
